import re,glob,collections,os
files=glob.glob('internal/**/*.go',recursive=True)+glob.glob('*.go')
decl={}
for f in glob.glob('internal/**/*.go',recursive=True):
 s=open(f).read()
 for m in re.finditer(r'\bfunc\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)\s*\(',s): decl.setdefault(m.group(1),[]).append(f)
counts=[]
for n,fs in decl.items():
 c=0; details=[]
 for f in files:
  s=open(f).read(); # remove declaration occurrence? count calls based followed (
  x=len(re.findall(r'\b'+re.escape(n)+r'\s*\(',s))
  c+=x
 counts.append((c-len(fs),n,fs))
for c,n,fs in sorted(counts,reverse=True)[:30]: print(c,n,','.join(fs))
